hunks.before:
replay:=private.daily_rate_correction_preview_replay_v1(p_args);
if replay is not null then return private.daily_rate_correction_public_assert_v1(replay,'PREVIEW');end if;
-- Lock the actual native context without comparing a stale digest until a
-- concurrent identical preview has had the chance to finish and replay.
perform private.daily_rate_correction_health_actor_require_v1(actor,false);
if current_setting('transaction_isolation') is distinct from 'read committed' then
 raise exception 'DAILY_RATE_LOCKED_CONTEXT_ISOLATION_REQUIRED' using errcode='55000';end if;
perform private.daily_rate_correction_context_v1((p_args->>'timesheet_id')::uuid,actor,true);
replay:=private.daily_rate_correction_preview_replay_v1(p_args);
if replay is not null then return private.daily_rate_correction_public_assert_v1(replay,'PREVIEW');end if;
daily:=private.daily_rate_correction_health_basis_v1(p_args,true);
prepared:=private.daily_rate_correction_health_review_prepare_v1(p_args);
if prepared->'daily' is distinct from daily then raise exception 'REVIEW_STALE' using errcode='40001';end if;

hunks.after:
enrollment:=private.daily_rate_correction_health_review_enroll_v1(p_args);
if jsonb_typeof(enrollment) is distinct from 'object'
 or not(enrollment ?& array['version','replayed','preview','prepared'])
 or enrollment-array['version','replayed','preview','prepared']<>'{}'::jsonb
 or enrollment->>'version' is distinct from 'DAILY_HEALTH_REVIEW_ENROLL_V1'
 or jsonb_typeof(enrollment->'replayed') is distinct from 'boolean' then
 raise exception 'DAILY_HEALTH_REVIEW_ENROLL_INVALID' using errcode='23514';end if;
if enrollment->'replayed'='true'::jsonb then
 if enrollment->'prepared' is distinct from 'null'::jsonb then raise exception 'DAILY_HEALTH_REVIEW_ENROLL_INVALID' using errcode='23514';end if;
 return private.daily_rate_correction_public_assert_v1(enrollment->'preview','PREVIEW');end if;
if enrollment->'preview' is distinct from 'null'::jsonb or jsonb_typeof(enrollment->'prepared') is distinct from 'object' then
 raise exception 'DAILY_HEALTH_REVIEW_ENROLL_INVALID' using errcode='23514';end if;
prepared:=enrollment->'prepared';daily:=prepared->'daily';
